<script lang="ts">import{bubbleReactionClassName,bubbleReactionCountClassName}from'@fex-design/styles/bubble';import{cn}from'@fex/utils';import type{Snippet}from'svelte';import type{HTMLButtonAttributes}from'svelte/elements';import Toggle from'../toggle/toggle.svelte';interface Props extends Omit<HTMLButtonAttributes,'children'|'onchange'>{pressed?:boolean;defaultPressed?:boolean;count?:number;onchange?:(value:boolean)=>void;children?:Snippet;render?:Snippet<[{props:Record<string,unknown>;state:{pressed:boolean;disabled:boolean}}]>}let{pressed,defaultPressed=false,count,disabled=false,onchange,class:className,children,render,...rest}:Props=$props();let state=$derived({pressed:pressed??defaultPressed,disabled:Boolean(disabled)});let binding=$derived({'data-slot':'bubble-reaction','data-state':state.pressed?'on':'off',class:cn(bubbleReactionClassName(),className)})</script>
